def entropy_weight(intensities):
    total = intensities.sum()
    if total <= 0:
        return intensities.copy()
    p = intensities / total
    S = -np.sum(p[p>0] * np.log2(p[p>0]))
    w = 1.0 if S >= 3.0 else (0.25 + 0.25 * S)
    return np.power(intensities, w)

def clean(peaks, tol, remove_precursor=False, pmz=None, noise_cutoff=0.0, normalize_to_half=True, merge_within=0.0):
    mz = peaks[:,0].astype(float).copy()
    inten = peaks[:,1].astype(float).copy()
    if remove_precursor and pmz is not None:
        mask = mz <= (pmz - 1.6)
        mz, inten = mz[mask], inten[mask]
    if noise_cutoff and noise_cutoff > 0:
        thr = inten.max()*noise_cutoff
        mask = inten >= thr
        mz, inten = mz[mask], inten[mask]
    inten = entropy_weight(inten)
    # merge within merge_within (Da)
    order = np.argsort(mz)
    mz, inten = mz[order], inten[order]
    if merge_within > 0 and mz.size > 1:
        nm, ni = [mz[0]], [inten[0]]
        for k in range(1, mz.size):
            if (mz[k]-nm[-1]) <= merge_within:
                tot = ni[-1]+inten[k]
                nm[-1] = (nm[-1]*ni[-1]+mz[k]*inten[k])/tot if tot>0 else mz[k]
                ni[-1] = tot
            else:
                nm.append(mz[k]); ni.append(inten[k])
