def xlog2(x):
    return np.where(x>0, x*np.log2(x), 0.0)

def greedy_pairs(mz_a, mz_b, tol):
    # greedy 1-to-1 matching, sort pairs by smallest mz-gap
    pairs = []
    for i in range(len(mz_a)):
        for j in range(len(mz_b)):
            if abs(mz_a[i]-mz_b[j]) <= tol:
                pairs.append((abs(mz_a[i]-mz_b[j]), i, j))
    pairs.sort()
    used_a=set(); used_b=set(); out=[]
    for d,i,j in pairs:
        if i in used_a or j in used_b: continue
        used_a.add(i); used_b.add(j); out.append((i,j))
    return out

def entropy_sim(peaks_a, peaks_b, tol, **kw):
    a = clean(peaks_a, tol, **kw)
    b = clean(peaks_b, tol, **kw)
    if a.size==0 or b.size==0: return 0.0
    pairs = greedy_pairs(a[:,0], b[:,0], tol)
    s = 0.0
    for i,j in pairs:
        ai, bj = a[i,1], b[j,1]
        s += xlog2(ai+bj) - xlog2(ai) - xlog2(bj)
    return s

